                "text_vn": "Vì nhờ mầu nhiệm Ngôi Lời nhập thể, việc trao đổi mầu nhiệm để cứu chuộc chúng con đã rạng ngời, đó là khi Ngôi Lời của Chúa mặc lấy bản tính yếu hèn của chúng con, thì bản tính phải chết của con người không những được nâng lên vinh dự muôn đời, mà nhờ sự kết hợp diệu kỳ đó, chúng con cũng được chia sẻ sự sống bất diệt.",
