          "eucharist_1": {
            "title": {
              "vn": "KINH TIỀN TỤNG THÁNH THỂ I - Hy lễ và bí tích của Đức Kitô"
            },
            "content": [
              {
                "text_vn": "Lạy Chúa là Cha chí thánh, là Thiên Chúa toàn năng hằng hữu, chúng con tạ ơn Chúa mọi nơi mọi lúc, nhờ Đức Kitô, Chúa chúng con, thật là chính đáng, phải đạo và đem lại ơn cứu độ cho chúng con.",
                "__massEditorPairKeys": {
                  "text_vn": "0:text"
                },
                "sp_vn": "LM."
              },
              {
                "text_vn": "Người là Tư Tế thật và hằng hữu, khi thiết lập thể thức hy lễ muôn đời, Người đã dâng mình cho Chúa làm của lễ ban ơn cứu độ trước tiên, và đã truyền cho chúng con dâng hy lễ đó để tưởng nhớ đến Người.",
                "__massEditorPairKeys": {
                  "text_vn": "1:text"
                }
              },
              {
                "text_vn": "Khi chúng con rước Mình Người hiến tế vì chúng con, chúng con được mạnh sức; và khi chúng con uống Máu Người đổ ra vì chúng con, chúng con được rửa sạch tội lỗi.",
                "__massEditorPairKeys": {
                  "text_vn": "2:text"
                }
              },
              {
                "text_vn": "Vì thế, cùng với các Thiên thần và Tổng lãnh Thiên thần, các Bệ thần và Quản thần, cùng toàn thể đạo binh thiên quốc, chúng con không ngừng hát bài ca chúc tụng vinh quang Chúa rằng:",
                "__massEditorPairKeys": {
                  "text_vn": "3:text"
                }
              }
            ]
          },
          "eucharist_2": {
            "title": {
              "vn": "KINH TIỀN TỤNG THÁNH THỂ II - Hiệu quả của bí tích Thánh Thể"
            },
            "content": [
              {
                "text_vn": "Lạy Chúa là Cha chí thánh, là Thiên Chúa toàn năng hằng hữu, chúng con tạ ơn Chúa mọi nơi mọi lúc, nhờ Đức Kitô, Chúa chúng con, thật là chính đáng, phải đạo và đem lại ơn cứu độ cho chúng con.",
                "__massEditorPairKeys": {
                  "text_vn": "0:text"
                },
                "sp_vn": "LM."
              },
              {
                "text_vn": "Trong bữa Tiệc Ly với các Tông Đồ, để lưu truyền tưởng niệm cứu độ của Thập Giá cho đến muôn đời, Người đã hiến dâng mình cho Chúa làm Con Chiên vẹn toàn, một hy lễ chúc tụng trọn hảo đẹp lòng Chúa.",
                "__massEditorPairKeys": {
                  "text_vn": "1:text"
                }
              },
              {
                "text_vn": "Chúa nuôi dưỡng và thánh hóa các tín hữu Chúa bằng bí tích cao trọng này, để một đức tin soi sáng và một đức ái liên kết nhân loại đang sống chung trên một trái đất. Vậy chúng con được đến gần bàn tiệc của bí tích diệu kỳ này, để khi đã tràn đầy ân sủng êm ái của Chúa, chúng con được biến đổi trở nên hình ảnh sống động của Chúa trên trời.",
                "__massEditorPairKeys": {
                  "text_vn": "2:text"
                }
              },
              {
                "text_vn": "Vì thế, mọi loài trên trời dưới đất đều thờ lạy và hát bài ca mới để chúc tụng Chúa; cùng với toàn thể đạo binh Thiên thần, chúng con không ngừng tung hô rằng:",
                "__massEditorPairKeys": {
                  "text_vn": "3:text"
                }
              }
            ]
          },
          "sacred_heart": {
            "title": {
              "vn": "KINH TIỀN TỤNG THÁNH TÂM CHÚA GIÊSU - Tình yêu vô biên của Đức Kitô"
            },
            "content": [
              {
                "text_vn": "Lạy Chúa là Cha chí thánh, là Thiên Chúa toàn năng hằng hữu, chúng con tạ ơn Chúa mọi nơi mọi lúc, nhờ Đức Kitô, Chúa chúng con, thật là chính đáng, phải đạo và đem lại ơn cứu độ cho chúng con.",
                "__massEditorPairKeys": {
                  "text_vn": "0:text"
                },
                "sp_vn": "LM."
              },
              {
                "text_vn": "Khi chịu treo trên Thập Giá, vì tình yêu lạ lùng, Người đã hiến thân vì chúng con. Từ cạnh sườn bị đâm thủng, Người đã để máu và nước chảy ra, hầu khơi nguồn các bí tích của Hội Thánh. Nhờ đó, khi mọi người được lôi kéo đến cùng Thánh Tâm rộng mở của Đấng Cứu Độ, họ sẽ luôn hân hoan múc tận nguồn ơn cứu độ.",
                "__massEditorPairKeys": {
                  "text_vn": "1:text"
                }
              },
              {
                "text_vn": "Vì thế, cùng với toàn thể các Thiên thần và các Thánh, chúng con ca ngợi Chúa và không ngừng tung hô rằng:",
                "__massEditorPairKeys": {
                  "text_vn": "2:text"
                }
              }
            ]
          },
          "holy_cross": {
            "title": {
              "vn": "Kinh Tiền Tụng Suy Tôn Thánh Giá"
            },
            "content": [
              {
                "text_vn": "Lạy Chúa là Cha chí thánh, là Thiên Chúa toàn năng hằng hữu, chúng con tạ ơn Chúa mọi nơi mọi lúc, thật là chính đáng, phải đạo và đem lại ơn cứu độ cho chúng con.",
                "__massEditorPairKeys": {
                  "text_vn": "0:text"
                },
                "sp_vn": "LM."
              },
              {
                "text_vn": "Chúa đã đặt ơn cứu độ nhân loại trên cây Thập Giá, để sự sống lại vọt ra từ nơi sự chết phát sinh, và để ma quỷ, kẻ đã thắng nhờ cây trái, cũng bị bại bại trên cây gỗ, nhờ Đức Kitô, Chúa chúng con.",
                "__massEditorPairKeys": {
                  "text_vn": "1:text"
                }
              },
              {
                "text_vn": "Nhờ Người, đạo binh các Thiên Thần ngợi khen, Tôn lãnh, Quyền thần kính sợ uy linh Chúa. Các tầng trời cùng với các dũng thần thiên quốc và các Thần Sốt Mến đồng thanh hoan hỷ chúc tụng Chúa. Xin cho chúng con được đồng thanh với các ngài thành khẩn tuyên xưng rằng:",
                "__massEditorPairKeys": {
                  "text_vn": "2:text"
                }
              }
            ]
          },
          "john_the_baptist": {
            "title": {
              "vn": "KINH TIỀN TỤNG SINH NHẬT THÁNH GIOAN TẨY GIẢ - Sứ mạng của vị Tiền Hô"
            },
            "content": [
              {
                "text_vn": "Lạy Chúa là Cha chí thánh, là Thiên Chúa toàn năng hằng hữu, chúng con tạ ơn Chúa mọi nơi mọi lúc, nhờ Đức Kitô, Chúa chúng con, thật là chính đáng, phải đạo và đem lại ơn cứu độ cho chúng con.",
                "__massEditorPairKeys": {
                  "text_vn": "0:text"
                },
                "sp_vn": "LM."
              },
              {
                "text_vn": "Chúng con ca ngợi những kỳ công của Chúa nơi thánh Gioan Tiền Hô, người Chúa đã thánh hiến và dành cho một vinh dự đặc biệt trong số những người sinh ra bởi người phụ nữ. Lúc chưa chào đời, thánh nhân đã nhảy mừng khi Đấng Cứu Độ nhân loại ngự đến. Lúc được sinh ra, thánh nhân đã đem lại niềm vui lớn lao. Trong các ngôn sứ, chỉ có thánh nhân đã chỉ cho thấy Chiên Thiên Chúa, Đấng cứu chuộc thế gian.",
                "__massEditorPairKeys": {
                  "text_vn": "1:text"
                }
              },
              {
                "text_vn": "Trong dòng sông Giođan, thánh nhân đã làm phép rửa cho chính Đấng thiết lập Phép Rửa, để thánh hóa nước thanh tẩy chúng con. Và sau cùng, để làm chứng cho chân lý cách tuyệt hảo, thánh nhân đã đổ máu đào.",
                "__massEditorPairKeys": {
                  "text_vn": "2:text"
                }
              },
              {
                "text_vn": "Vì thế, cùng với các Dũng thần thiên quốc, ở dưới đất chúng con hằng ca ngợi và không ngừng tung hô uy linh Chúa rằng:",
                "__massEditorPairKeys": {
                  "text_vn": "3:text"
                }
              }
            ]
          },
