                "text_vn": "Lạy Chúa là Cha chí thánh, là Thiên Chúa toàn năng hằng hữu, chúng con tạ ơn Chúa mọi nơi mọi lúc, nhờ Đức Kitô, Chúa chúng con, thật là chính đáng, phải đạo và đem lại ơn cứu độ cho chúng con.",
