                "text_vn": "Vì hôm nay Chúa cho chúng con được mừng kinh thánh đô của Chúa là thành Giêrusalem trên trời, cũng là mẹ của chúng con. Tại đó, các anh chị em chúng con là cộng đoàn các thánh đang muôn đời ca ngợi Chúa. Trên đường lữ hành, chúng con chỉ có đức tin làm đuốc sáng, chúng con đang hăm hở tiến về đó,",
