                "text_vn": "Xin Thiên Chúa toàn năng và từ bi, nhờ việc Con Chúa đến trong ánh huy hoàng, thánh hoá và đổ tràn phúc lành của Ngài cho anh chị em là những kẻ tin Con Một Chúa đã đến và mong đợi Người sẽ đến.",
