                "text_vn": "Nhờ mầu nhiệm Ðức Giêsu sống lại Thiên Chúa đã cứu chuộc và dẫn đưa anh chị em vào đời sống mới, xin Người cũng cho anh chị em được hưởng phúc trường sinh.",
