                "text_vn": "Anh chị em tin Ðức Ki-tô đang uy linh hiển trị cùng Chúa Cha, ước chi anh chị em cũng có thể vui mừng cảm nghiệm được Người đang ở cùng anh chị em mọi ngày cho đến tận thế như lời Người đã hứa.",
