                "text_vn": "Thiên Chúa đã cho anh chị em đứng vững trên nền tảng các Tông Đồ, vì công phúc vinh hiển của các Thánh Tông Đồ (…) và (…) (Thánh … Tông Đồ), xin Chúa đoái thương ban phúc lành cho anh chị em.",
