                "text_vn": "Thiên Chúa đã muốn ban tặng anh chị em bằng chứng và gương sáng của các Thánh Tông Đồ, vì sự phù trợ của các ngài, xin Chúa làm cho anh chị em nên chứng nhân chân lý cho mọi người.",
