  const deepMerge = (left, right) => {
    if (Array.isArray(left) || Array.isArray(right)) {
      const a = Array.isArray(left) ? left : [];
      const b = Array.isArray(right) ? right : [];
      return Array.from({
        length: Math.max(a.length, b.length)
      }, (_, index) => deepMerge(a[index], b[index]));
    }
    if (left && typeof left === 'object' || right && typeof right === 'object') {
      const result = Object.assign({}, left && typeof left === 'object' ? left : {});
      Object.entries(right && typeof right === 'object' ? right : {}).forEach(([key, value]) => {
        result[key] = key in result ? deepMerge(result[key], value) : value;
      });
      return result;
    }
    return right === undefined ? left : right;
  };
  const rebuild = () => {
    const order = ['KR', 'VN', 'US', 'JP', 'VA'];
    global.missaData = order.reduce((combined, key) => {
      const ordinary = global.countryMassData[key] && global.countryMassData[key].ordinary;
      return Array.isArray(ordinary) ? deepMerge(combined, ordinary) : combined;
    }, []);
    global.ordoMissaDataApi = Object.freeze({
      entries: global.missaData,
      cloneEntries() {
        return JSON.parse(JSON.stringify(global.missaData));
      },
      findEucharisticSongEntry() {
        return global.missaData.find(item => item && item.songs) || null;
      },
      findEucharisticPrayerThreeEntry() {
        return global.missaData.find(item => item && item.forms && Array.isArray(item.forms['3'])) || null;
      }
    });
  };
  rebuild();
